17	/**
18	 * Softmax forward kernel.
19	 *
20	 * Computes softmax(x) = exp(x - max(x)) / sum(exp(x - max(x)))
21	 *
22	 * Template Parameters:
23	 *   T: Element type (float, __half, __nv_bfloat16)
24	 *   BLOCK_SIZE: Tile size (power of 2, must equal n_cols)
25	 *
26	 * Parameters:
27	 *   output: Pointer to output tensor (n_rows, n_cols)
28	 *   input: Pointer to input tensor (n_rows, n_cols)
29	 *   input_row_stride: Stride for input rows
30	 *   output_row_stride: Stride for output rows
31	 *   n_rows: Number of rows
32	 *   n_cols: Number of columns (power of 2, must equal BLOCK_SIZE)
33	 *   num_programs: Total number of CTA programs for persistent scheduling
34	 */
35	template<typename T, int BLOCK_SIZE>
36	__tile_global__ void softmax_kernel(
37	    T* __restrict__ _output,
38	    const T* __restrict__ _input,
39	    int input_row_stride,
40	    int output_row_stride,
41	    int n_rows,
42	    int n_cols,
43	    int num_programs
44	) {
45	    namespace ct = cuda::tiles;
46	    using namespace ct::literals;
47	
48	    // Apply alignment hints for better memory access
49	    const T* input = ct::assume_aligned<16>(_input);
50	    T* output = ct::assume_aligned<16>(_output);
51	
52	    using f32xN = ct::tile<float, ct::shape<BLOCK_SIZE>>;
53	    using TxN = ct::tile<T, ct::shape<BLOCK_SIZE>>;
54	    using i32xN = ct::tile<int, ct::shape<BLOCK_SIZE>>;
55	
56	    // Persistent scheduling: each program handles multiple rows
57	    int row_start = ct::bid().x;
58	    int row_step = num_programs;
59	
60	    for (auto row_idx : ct::irange(row_start, n_rows, row_step)) {
61	        // row_start_ptr = input + row_idx * input_row_stride
62	        const T* row_start_ptr = input + row_idx * input_row_stride;
63	
64	        auto col_offsets = ct::iota<i32xN>();
65	
66	        // Create mask for valid columns (handles non-power-of-2 n_cols)
67	        auto mask = col_offsets < n_cols;
68	
69	        // input_ptrs = row_start_ptr + col_offsets
70	        auto input_ptrs = row_start_ptr + col_offsets;
71	
72	        // Load with mask, padding invalid elements with -infinity
73	        // so they don't affect max/sum calculations
74	        auto neg_inf_pad = ct::full<TxN>(T(-INFINITY));
75	        auto row_T = ct::load_masked(input_ptrs, mask, neg_inf_pad);
76	        auto row = ct::element_cast<float>(row_T);
77	
78	        float row_max = static_cast<float>(ct::reduce_max(row, 0_ic));
79	
80	        // row_minus_max = row - row_max
81	        auto row_minus_max = row - row_max;
82	
83	        // exp(-inf - max) = 0, so masked elements contribute 0
84	        auto numerator = ct::exp(row_minus_max);
85	
86	        float denominator = static_cast<float>(ct::sum(numerator, 0_ic));
87	
88	        // softmax_output = numerator / denominator
89	        auto softmax_output = numerator / denominator;
90	
91	        // Convert back to output type and store (only valid columns)
92	        auto softmax_output_T = ct::element_cast<T>(softmax_output);
93	        auto output_ptrs = output + row_idx * output_row_stride + col_offsets;
94	        ct::store_masked(output_ptrs, softmax_output_T, mask);
95	    }
