145	        auto row_T = ct::load_masked(row_ptr + col_offsets, mask, neg_inf_pad);
146	        auto row = ct::element_cast<float>(row_T);
147	
148	        float block_max = static_cast<float>(ct::reduce_max(row, 0_ic));
149	        float m_curr = (block_max > m_prev) ? block_max : m_prev;
150	
151	        l_prev *= ct::exp(m_prev - m_curr);
152	
153	        auto p = ct::exp(row - m_curr);
154	
155	        float l_block = static_cast<float>(ct::sum(p, 0_ic));
156	
157	        l_prev += l_block;
158	        m_prev = m_curr;
159	    }
160	
161	    for (auto block_idx : ct::irange(0, num_blocks)) {
162	        int start_col = block_idx * BLOCK_SIZE;
163	
164	        auto col_offsets = ct::full<i32xN>(start_col) + ct::iota<i32xN>();
165	        auto mask = col_offsets < n_cols;
166	
167	        auto row_T = ct::load_masked(row_ptr + col_offsets, mask, neg_inf_pad);
168	        auto row = ct::element_cast<float>(row_T);
169	
170	        auto row_minus_max = row - m_prev;
171	        auto numerator = ct::exp(row_minus_max);
172	        auto softmax_output = numerator / l_prev;
173	
